-- Create "pm_settings" table
CREATE TABLE `pm_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `new_message_subject` text NOT NULL, `new_message_body` text NOT NULL, PRIMARY KEY (`id`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "pm_threads" table
CREATE TABLE `pm_threads` (`id` int unsigned NOT NULL AUTO_INCREMENT, `subject` varchar(255) NOT NULL DEFAULT '', `created_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `updated_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), PRIMARY KEY (`id`), INDEX `pmthread_updated_at` (`updated_at`), INDEX `pmthread_created_at` (`created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "pm_messages" table
CREATE TABLE `pm_messages` (`id` int unsigned NOT NULL AUTO_INCREMENT, `body` longtext NOT NULL, `created_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `author_id` int unsigned NULL, `thread_id` int unsigned NOT NULL, PRIMARY KEY (`id`), INDEX `pmmessage_thread_id_created_at` (`thread_id`, `created_at`), INDEX `pmmessage_thread_id_id` (`thread_id`, `id`), INDEX `pmmessage_author_id_created_at` (`author_id`, `created_at`), CONSTRAINT `pm_messages_users_author` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE SET NULL, CONSTRAINT `pm_messages_pm_threads_messages` FOREIGN KEY (`thread_id`) REFERENCES `pm_threads` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "pm_thread_members" table
CREATE TABLE `pm_thread_members` (`id` int unsigned NOT NULL AUTO_INCREMENT, `is_new` bool NOT NULL DEFAULT true, `deleted` bool NOT NULL DEFAULT false, `joined_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `thread_id` int unsigned NOT NULL, `user_id` int unsigned NOT NULL, PRIMARY KEY (`id`), INDEX `pmthreadmember_user_id_deleted_is_new` (`user_id`, `deleted`, `is_new`), INDEX `pmthreadmember_user_id_deleted_is_new_thread_id` (`user_id`, `deleted`, `is_new`, `thread_id`), INDEX `pmthreadmember_thread_id_deleted` (`thread_id`, `deleted`), UNIQUE INDEX `pm_thread_members_thread_user` (`thread_id`, `user_id`), CONSTRAINT `pm_thread_members_pm_threads_members` FOREIGN KEY (`thread_id`) REFERENCES `pm_threads` (`id`) ON DELETE CASCADE, CONSTRAINT `pm_thread_members_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "pm_user_settings" table
CREATE TABLE `pm_user_settings` (`id` int unsigned NOT NULL AUTO_INCREMENT, `mail_new_message` bool NOT NULL DEFAULT true, `user_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `pmusersettings_user_id` (`user_id`), CONSTRAINT `pm_user_settings_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
